function reviewSource(id) {
  const s=state.sources.find(x=>x.id===id);
  openModal('Record source validation', `<form id="source-review-form"><input type="hidden" name="source_id" value="${esc(id)}"><p>${esc(s.title)}</p>
    <label class="mt">Validation status<select name="validation">${['Reviewed','Verified','Outdated'].map(v=>option(v,s.validation)).join('')}</select></label>
    ${[['tested','Test evidence recorded'],['customer_confirmed','Customer confirmation recorded'],['deployed','Production deployment recorded']].map(([k,label])=>`<label class="check"><input type="checkbox" name="${k}" ${s.validation_evidence?.[k]?'checked':''}>${label}</label>`).join('')}
    <label class="mt">Conflicts with (comma-separated source IDs)<input name="conflicts_with" maxlength="2100" value="${esc((s.conflicts_with || []).join(', '))}"></label>
    <label class="mt">Review notes and evidence references<textarea name="notes" required maxlength="12000">${esc(s.review_notes || '')}</textarea></label>
    <div class="form-actions"><button type="submit" class="btn primary">Save validation</button></div></form>`);
}
function lifecyclePanel(x) {
  const lifecycle=x.lifecycle || {stages:[],current_stage:'Lifecycle not tracked for this imported record',history_tracked:false,next_stage:null};
  const progress=lifecycle.stages.map(stage=>`<div class="lifecycle-stage ${stage.state}"><span class="lifecycle-dot">${stage.state==='completed'?'✓':stage.state==='current'?'●':'○'}</span><span>${esc(stage.name)}</span><small>${stage.state==='completed'?'Completed':stage.state==='current'?'Current':'Upcoming'}</small></div>`).join('');
  const rejected=x.type==='Change request'&&x.lifecycle_stage==='Approval'&&x.approval_decision?.status==='Rejected';
  const action=rejected?'<button class="btn primary" data-action="close-rejected">Record closure after rejected approval</button>':lifecycle.next_stage ? `<button class="btn primary" data-action="advance-lifecycle">${lifecycle.next_stage==='Closure'?'Record closure':'Advance to '+esc(lifecycle.next_stage)}</button>` : '';
  const approval=(x.type==='Change request'&&x.lifecycle_stage==='Approval')?`<div class="gap-alert"><strong>Customer approval: ${esc(x.approval_decision?.status || 'Pending')}</strong><p>${esc(x.approval_decision?.notes || 'Record a customer decision before development.')}</p>${x.approval_decision?.status==='Pending'?'<button class="btn small" data-action="approval">Record approval decision</button>':''}</div>`:'';
  const verification=x.type==='Change request'&&x.lifecycle_stage==='Verification'?`<div class="gap-alert"><strong>Post-deployment verification: ${esc(x.verification?.result || 'Pending')}</strong>${x.verification?.notes?`<p>${esc(x.verification.notes)}</p>`:''}<button class="btn small" data-action="verification">${x.verification?'Record another verification result':'Record verification result'}</button>${x.verification_history?.length>1?`<small>${x.verification_history.map(v=>`${time(v.at)} · ${esc(v.result)} · ${esc(v.notes)}`).join(' | ')}</small>`:''}</div>`:'';
  return `<section class="panel lifecycle-panel"><div class="panel-head"><div><h2>Ticket lifecycle</h2><p>Current stage: <strong>${esc(lifecycle.current_stage)}</strong></p></div>${x.lifecycle_stage==='Closure'?badge('Closed'):action}</div><div class="lifecycle-track">${progress}</div>${!lifecycle.history_tracked?'<p class="hint">Stage history was not tracked for this imported ticket. No earlier steps have been inferred or marked complete.</p>':''}${approval}${verification}${lifecycle.history?.length?`<div class="lifecycle-history"><strong>Stage history</strong>${lifecycle.history.map(h=>`<div><span>${esc(h.stage)}</span><small>${time(h.at)} · ${esc(h.author)} · ${esc(h.notes)}</small></div>`).join('')}</div>`:''}</section>`;
}
function lifecycleModal(stageOverride='') {
  const lifecycle=current.lifecycle || {};
  const target=stageOverride || lifecycle.next_stage;
  if(!target)return toast('No next lifecycle stage is available.');
  const showApproval=target==='Approval', showException=target==='Closure';
  openModal(`Advance lifecycle · ${target}`, `<form id="lifecycle-form"><input type="hidden" name="stage" value="${esc(target)}"><p class="hint">This records a real stage transition and timestamp. Viewing a stage does not complete it.</p>
    ${showApproval?`<label>Approval status<select name="approval_status"><option>Pending</option><option>Approved</option><option>Rejected</option></select></label>`:''}
    ${showException?`<label>Closure exception<select name="exception_reason"><option value="">Normal closure</option><option>Cancelled</option><option>Escalated</option><option>Other</option>${current.type==='Change request'&&current.approval_decision?.status==='Rejected'?'<option selected>Approval rejected</option>':''}</select></label>`:''}
    <label class="mt">Transition notes<textarea name="notes" required maxlength="4000" placeholder="Record the action taken, decision, evidence reference, or reason."></textarea></label>
    <div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">Save stage transition</button></div></form>`);
}
function approvalModal() {
  openModal('Record customer approval', `<form id="approval-form"><p class="hint">Record an actual customer decision. Development remains blocked until approval is Approved.</p><label>Approval status<select name="status"><option>Pending</option><option>Approved</option><option>Rejected</option></select></label><label class="mt">Decision notes and reference<textarea name="notes" required maxlength="4000"></textarea></label><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">Save approval decision</button></div></form>`);
}
async function readUpload(file) {
  if(file.size>5*1024*1024)throw new Error('Upload a file no larger than 5 MB.');
  const bytes=new Uint8Array(await file.arrayBuffer());let binary='';
  for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));
  return api('/extract',{filename:file.name,file_base64:btoa(binary)});
}
document.addEventListener('click', async event => {
  const el=event.target.closest('button'); if(!el)return; const prior=el.innerHTML;
  try {
    if(el.dataset.source) return sourceModal(el.dataset.source);
    const action=el.dataset.action;
    if(action==='close')return $('#modal').close();
    if(action==='new')return newInvestigation();
    if(action==='advance-lifecycle')return lifecycleModal();
    if(action==='close-rejected')return lifecycleModal('Closure');
    if(action==='approval')return approvalModal();
    if(action==='verification')return verificationModal();
    if(action==='manual'){draft={title:'',description:'',ticket_id:'',application:'',version:'',error_code:'',customisation:'',type:'Incident',priority:'Medium',timeline:[]};return reviewDraft();}
    if(action==='knowledge-new')return knowledgeForm();
    if(action==='promote'){
      const o=current.outcome;
      if(!o||!['Worked','Resolved','Workaround','Alternative solution used'].includes(o.status)){toast('Only worked fixes, explicitly labeled workarounds, or validated alternative solutions can become knowledge drafts.');return;}
      if(['Worked','Resolved','Alternative solution used'].includes(o.status)&&(!o.tested||!o.customer_confirmed||(current.type==='Change request'&&(!o.approved||!o.developed||!o.deployed||!o.verified)))){toast('Record the required testing, customer confirmation, and change evidence before creating a knowledge draft.');return;}
      const history=current.timeline.filter(e=>!['Intake','Outcome'].includes(e.kind)).map(e=>`${e.at} ${e.kind}: ${e.text}`).join('\n');
      return knowledgeForm({title:current.title,customer:current.customer,application:current.application,platform:current.platform,module:current.module,business_process:current.business_process,version:current.version,error_code:current.error_code,customisation:current.customisation,solution_kind:o.status==='Workaround'?'Workaround':'Likely solution',source_type:'Historical ticket',source_reference:current.ticket_id || current.id,content:`Ticket: ${current.ticket_id || current.id}\nCustomer scope: ${current.customer}\nApplication: ${current.application}\nPlatform / module / release: ${current.platform || 'Unknown'} / ${current.module || 'Unknown'} / ${current.version || 'Unknown'}\nIssue: ${current.description}\nOutcome: ${o.status}\nResolution: ${o.alternative_solution || o.notes}\nInvestigation history:\n${history}`});
    }
    if(action==='review-source')return reviewSource(el.dataset.id);
    if(action==='reindex'){el.disabled=true;el.textContent='Indexing…';const source=await api(`/sources/${el.dataset.id}/reindex`,{});await refresh();sourceModal(source.id);toast(source.index_status==='Ready'?'Source indexed.':source.index_error);}
    if(action==='check-ai'){el.disabled=true;el.textContent='Checking…';try{await api('/ai/check',{});aiConnection='Connected';await refresh();toast('Gemini generation verified with one request.');}catch(error){aiConnection='Check failed';await refresh();throw error;}}

    if(action==='analyze') {el.disabled=true;el.textContent='Searching permitted evidence…';await api(`/investigations/${current.id}/analyze`,{});await refresh();go(`investigations/${current.id}/recommendations`);toast('Evidence search complete. Review applicability before selecting a solution.');}
    if(el.dataset.decision){el.disabled=true;await api(`/investigations/${current.id}/decision`,{source_id:el.dataset.id,decision:el.dataset.decision});await refresh();toast(el.dataset.decision==='Accepted'?'Selected for validation. Record test evidence before the outcome.':'Recommendation rejected.');}
    if(action==='retry'){try{await refresh();}catch(e){showConnectionError(e);}}
  }catch(error){formError(error.message);}finally{el.disabled=false;if(el.isConnected)el.innerHTML=prior;}
});
document.addEventListener('input',event=>{
  if(event.target.id==='ticket-search'){filters.q=event.target.value;$('#tickets-table').innerHTML=ticketTable(filteredTickets());}
  if(event.target.id==='knowledge-search'){knowledge.q=event.target.value;$('#knowledge-results').innerHTML=sourceCards();}
});
document.addEventListener('change',async event=>{
  const {id,value}=event.target;
  if(id==='knowledge-file' && event.target.files[0]){const submit=$('#source-form button[type=submit]');submit.disabled=true;try{const result=await readUpload(event.target.files[0]);$('#knowledge-content').value=result.content;$('#knowledge-filename').value=result.filename;toast('Document extracted. Review the text before saving.');}catch(e){formError(e.message);}finally{submit.disabled=false;}return;}
  if(id==='status-filter'||id==='type-filter'){filters[id==='status-filter'?'status':'type']=value;$('#tickets-table').innerHTML=ticketTable(filteredTickets());}
  if(id==='source-filter'){knowledge.type=value;$('#knowledge-results').innerHTML=sourceCards();}
});
document.addEventListener('submit',async event=>{
  event.preventDefault(); const form=event.target, submit=$('button[type="submit"]',form), original=submit?.innerHTML;
  if(submit){submit.disabled=true;submit.textContent='Saving…';}
  try {
    if(form.id==='lifecycle-form'){
      const data=Object.fromEntries(new FormData(form));await api(`/investigations/${current.id}/lifecycle`,data);$('#modal').close();await refresh();toast('Lifecycle stage saved with timestamp and audit note.');
    }
    if(form.id==='approval-form'){
      const data=Object.fromEntries(new FormData(form));await api(`/investigations/${current.id}/approval`,data);$('#modal').close();await refresh();toast('Customer approval decision recorded.');
    }
    if(form.id==='verification-form'){
      const data=Object.fromEntries(new FormData(form));await api(`/investigations/${current.id}/verification`,data);$('#modal').close();await refresh();toast('Post-deployment verification result saved.');
    }
    if(form.matches('.solutioning-form')){
      const data=Object.fromEntries(new FormData(form)),section=form.dataset.section;await api(`/investigations/${current.id}/solutioning`,{section,fields:data});await refresh();toast(`${section==='functional'?'Functional':'Technical'} solutioning saved to this ticket.`);
    }
    if(form.id==='source-form'){
      const data=Object.fromEntries(new FormData(form));data.generalized_confirmed=Boolean($('[name="generalized_confirmed"]',form).checked);
      const source=await api('/sources',data);$('#modal').close();await refresh();go('knowledge');toast(source.index_status==='Ready'?'Knowledge saved and indexed.':`Document saved. ${source.index_error}`);
    }
    if(form.id==='source-review-form'){
      const data=Object.fromEntries(new FormData(form));for(const key of ['tested','customer_confirmed','deployed'])data[key]=Boolean(data[key]);await api(`/sources/${data.source_id}/review`,data);await refresh();sourceModal(data.source_id);toast('Validation recorded.');
    }
    if(form.id==='intake-form'){
      const file=$('#ticket-file').files[0];let content=$('#intake-content').value,filename='';
      if(file){const extracted=await readUpload(file);content=extracted.content;filename=extracted.filename;}
      draft=await api('/intake',{content,filename});reviewDraft();
    }
    if(form.id==='create-form'){
      const data={...Object.fromEntries(new FormData(form)),timeline:draft.timeline,customer:state.customer};
      const item=await api('/investigations',data);$('#modal').close();await refresh();go(`investigations/${item.id}/overview`);toast('Investigation created. Review the context and find supporting evidence.');
    }
    if(form.id==='note-form'){
      const note=Object.fromEntries(new FormData(form)),file=$('#note-file').files[0];if(file){const extracted=await readUpload(file);note.text+=(note.text?'\n':'')+extracted.filename+'\n'+extracted.content;note.source_reference=extracted.filename;note.kind='Attachment';}await api(`/investigations/${current.id}/note`,note);await refresh();toast('Evidence saved. Run a fresh search to include your findings.');
    }
    if(form.id==='outcome-form'){
      const data=Object.fromEntries(new FormData(form));for(const key of ['tested','customer_confirmed','approved','developed','deployed','verified'])data[key]=Boolean(data[key]);
      await api(`/investigations/${current.id}/outcome`,data);await refresh();toast('Outcome recorded. Your investigation trail is saved in MongoDB.');
    }
  }catch(error){formError(error.message);}finally{if(submit){submit.disabled=false;submit.innerHTML=original;}}
});
window.addEventListener('hashchange',render);
refresh().catch(showConnectionError);
function showConnectionError(error) {
  $('#app').innerHTML=`<main class="setup-screen"><strong class="setup-brand">Solution ATLAS</strong><h1>Connect your workspace</h1><p class="inline-error">${esc(error.message)}</p>
  <section class="panel"><div class="panel-body"><h2>Configure .env</h2><p class="mt">Set <code>MONGODB_URI</code> to your MongoDB connection string and add your <code>GEMINI_API_KEY</code>. Restart the server after editing.</p><p class="mt">For local MongoDB, start Docker Desktop and run <code>docker compose up -d mongodb</code>. MongoDB Atlas works with its connection URI too.</p><p class="hint">Workspace records load from the configured MongoDB database.</p></div></section><div class="mt">${btn('Retry connection','retry',true)}</div></main>`;
}
